import{_ as t,o as a,c as e,a2 as i}from"./chunks/framework.CjPXnAcb.js";const g=JSON.parse('{"title":"HTTP 与 API —— 程序之间怎么对话","description":"","frontmatter":{"title":"HTTP 与 API —— 程序之间怎么对话"},"headers":[],"relativePath":"prereq/05-http-and-api.md","filePath":"prereq/05-http-and-api.md","lastUpdated":1789060104000}'),n={name:"prereq/05-http-and-api.md"};function p(o,s,l,r,d,h){return a(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="_05-·-http-与-api-调大模型前必须懂的一顿饭" tabindex="-1">05 · HTTP 与 API：调大模型前必须懂的一顿饭 <a class="header-anchor" href="#_05-·-http-与-api-调大模型前必须懂的一顿饭" aria-label="Permalink to &quot;05 · HTTP 与 API：调大模型前必须懂的一顿饭&quot;">​</a></h1><blockquote><p>一句话说清这课解决什么问题：让你明白「调用大模型 API」这句话背后到底发生了什么——其实就是让你的程序向远方的服务器下一份「电子订单」。</p></blockquote><h2 id="它是什么-大白话-生活比喻" tabindex="-1">它是什么？（大白话 + 生活比喻） <a class="header-anchor" href="#它是什么-大白话-生活比喻" aria-label="Permalink to &quot;它是什么？（大白话 + 生活比喻）&quot;">​</a></h2><p><strong>HTTP</strong> 是浏览器和服务器之间约定好的「对话语言」。你每次打开网页，背后都是一场对话：浏览器提一个<strong>请求</strong>（request，顾客下单），服务器回一个<strong>响应</strong>（response，服务员端菜上桌回话）。</p><p>把它想象成去餐厅吃饭：</p><ul><li><strong>你进餐厅看菜单</strong> → 浏览器向网站要网页</li><li><strong>你下单</strong> → 浏览器向服务器提交数据（比如登录表单）</li><li><strong>服务员回话「菜来了」或「没这道菜」</strong> → 服务器返回成功或错误</li></ul><p>对话总要有个「点谁」。<strong>URL</strong>（网址）就是订单上的地址，它由三段组成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://open.bigmodel.cn/api/paas/v4/</span></span>
<span class="line"><span>└─协议┘└────域名────┘└────路径────┘</span></span></code></pre></div><ul><li><strong>协议</strong>：用什么规则对话，<code>https</code> 表示加密过的 HTTP，放心传秘密。</li><li><strong>域名</strong>：哪家店，<code>open.bigmodel.cn</code> 就是智谱的服务器。</li><li><strong>路径</strong>：店里哪个窗口，<code>/api/paas/v4/</code> 表示「AI 服务的四号窗口」。</li></ul><p>在餐厅里点菜有两种典型动作，HTTP 里也有：</p><ul><li><strong>GET</strong> = 看菜单：只是<strong>拿数据</strong>，不改变什么。</li><li><strong>POST</strong> = 下单：<strong>交数据</strong>过去，让服务器办事（比如把你写的对话交给 AI）。</li></ul><p>服务员回话时带一个<strong>状态码</strong>（status code，三个数字表示结果），常见的用吃饭来记：</p><table tabindex="0"><thead><tr><th>状态码</th><th>大白话</th></tr></thead><tbody><tr><td>200</td><td>菜来了，一切正常</td></tr><tr><td>404</td><td>没这道菜（地址/路径写错了）</td></tr><tr><td>401</td><td>会员卡无效（没登录 / Key 不对）</td></tr><tr><td>500</td><td>厨房着火了（服务器自己出了故障）</td></tr></tbody></table><h2 id="为什么我们需要它" tabindex="-1">为什么我们需要它？ <a class="header-anchor" href="#为什么我们需要它" aria-label="Permalink to &quot;为什么我们需要它？&quot;">​</a></h2><p>因为<strong>API</strong> 就是「程序对程序的服务窗口」：API（Application Programming Interface，应用程序接口）让一个程序不用打开网页点鼠标，直接用代码向另一个程序要东西、交东西。</p><p>你的项目正是这样：你要写的不是「ChatGPT 网页」，而是<strong>自己的程序调用智谱 GLM 的 API</strong>。点这顿饭需要三样东西：</p><ol><li><strong>API Key</strong>：会员卡号，一串只有你知道的密码。服务器靠它证明「你是谁、给你记账收费」。之后去 <a href="https://open.bigmodel.cn" target="_blank" rel="noreferrer">https://open.bigmodel.cn</a> 注册就能拿到。</li><li><strong>JSON</strong>：点菜单的标准格式。JSON（JavaScript Object Notation）是一种「键值对」写法——冒号左边是名字，右边是内容，人和程序都好读：</li></ol><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;glm-4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;messages&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;role&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;你好，介绍一下你自己&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ol start="3"><li><strong>那个地址</strong>：<a href="https://open.bigmodel.cn/api/paas/v4/" target="_blank" rel="noreferrer">https://open.bigmodel.cn/api/paas/v4/</a> ，这是智谱的 OpenAI 兼容接口（意思是它学着 OpenAI 的订单格式做菜，你以后换工具、抄教程都方便）。</li></ol><p>一句话总结未来的项目：<strong>调大模型 API = POST 一段对话 JSON 过去，服务器把 AI 的回复 JSON 发回来。</strong> 就这么简单。</p><h2 id="动手试一试" tabindex="-1">动手试一试 <a class="header-anchor" href="#动手试一试" aria-label="Permalink to &quot;动手试一试&quot;">​</a></h2><p>先执行下面这条命令，把 <code>requests</code> 工具包装好（它是做什么的、为什么这么写，下一课 06 细讲）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>py -m pip install requests</span></span>
<span class="line"><span>rem 用 Python 自带的 pip 装 requests 这个第三方包</span></span></code></pre></div><p>然后新建 <code>test_api.py</code>：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> requests  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 引入发请求的工具包</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">resp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> requests.get(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://api.github.com/zen&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># GET 一个公开测试接口</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(resp.status_code)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 打印状态码，期待 200</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(resp.text)         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 打印服务器返回的正文</span></span></code></pre></div><p>逐行解释：</p><ul><li><code>import requests</code> → 把「发 HTTP 请求」的工具搬进你的程序。</li><li><code>requests.get(网址)</code> → 向这个地址发一个 <strong>GET</strong> 请求（看菜单），返回值存进 <code>resp</code>。</li><li><code>resp.status_code</code> → 服务员的回话编号，<code>200</code> 就是成功。</li><li><code>resp.text</code> → 回话的正文内容。GitHub 这个接口会回一句随机哲理短句，很有趣。</li></ul><p>跑起来看到 <code>200</code> 和一句英文，恭喜——你已经完成了一次真正的 HTTP 对话。以后调 GLM，只是把 <code>get</code> 换成 <code>post</code>、附上 API Key 和 JSON 菜单而已。</p><h2 id="常见报错与怎么读它" tabindex="-1">常见报错与怎么读它 <a class="header-anchor" href="#常见报错与怎么读它" aria-label="Permalink to &quot;常见报错与怎么读它&quot;">​</a></h2><p><strong>案例一：网不通。</strong> 报错原文长这样（最后一行是重点）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>requests.exceptions.ConnectionError:</span></span>
<span class="line"><span>HTTPSConnectionPool(host=&#39;api.github.com&#39;, port=443):</span></span>
<span class="line"><span>Max retries exceeded with url: /zen</span></span>
<span class="line"><span>(Caused by NameResolutionError(&quot;Failed to resolve &#39;api.github.com&#39;&quot;))</span></span></code></pre></div><p>怎么读：<strong>先看异常类型的最后一行</strong>。类型是 <code>ConnectionError</code>——「连不上」；括号里 <code>Failed to resolve</code> 说明连域名都没解析出来。线索指向：网断了、代理没开，或<strong>网址打错了</strong>。解决顺序：先确认能上网 → 再核对 URL 有没有拼错（比如少个字母、多了空格）。注意这和 404 不同：404 是「店找到了但没这道菜」，ConnectionError 是「店根本找不到」。</p><p><strong>案例二：会员卡无效。</strong> 程序不报错，但打印的状态码是 <code>401</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>401</span></span>
<span class="line"><span>{&quot;error&quot;: {&quot;code&quot;: &quot;401&quot;, &quot;message&quot;: &quot;Invalid API key&quot;}}</span></span></code></pre></div><p>怎么读：异常没有抛出，所以这次要看<strong>状态码</strong>。<code>401</code> 对照上表 = 会员卡无效；再看正文 JSON 里的 <code>message</code>，明说 <code>Invalid API key</code>。解决：检查 Key 有没有复制全、有没有漏掉传给服务器的那一步（以后代码里是往请求头 headers 里放 Key，忘了放就会 401）。</p><p>养成肌肉记忆：<strong>报错先看异常最后一行，没异常先看状态码</strong>，这两个信息能解决九成问题。</p><h2 id="自测两题" tabindex="-1">自测两题 <a class="header-anchor" href="#自测两题" aria-label="Permalink to &quot;自测两题&quot;">​</a></h2><p><strong>第 1 题</strong>：把一段对话发给智谱 GLM 让它回复，应该用 GET 还是 POST？状态码 500 大概是谁的问题？</p><details class="details custom-block"><summary>点击看答案</summary><p>用 <strong>POST</strong>——你在「交数据」让服务器办事，属于下单而不是看菜单。500 = 厨房着火，是<strong>服务器那边</strong>的问题（智谱的机器出故障了），不是你的代码错，等一会儿重试即可。</p></details><p><strong>第 2 题</strong>：<code>https://open.bigmodel.cn/api/paas/v4/</code> 这串地址里，域名是哪一段？状态码 401 和 404 分别说明什么？</p><details class="details custom-block"><summary>点击看答案</summary><p>域名是 <code>open.bigmodel.cn</code>；<code>https</code> 是协议，<code>/api/paas/v4/</code> 是路径。401 = 会员卡无效，即 API Key 没传对；404 = 没这道菜，即 URL 路径写错了（或接口地址不存在）。</p></details><h2 id="下一课" tabindex="-1">下一课 <a class="header-anchor" href="#下一课" aria-label="Permalink to &quot;下一课&quot;">​</a></h2><p>你懂了「对话规则」，下一课补上「工具箱」：<strong>Python 环境与 pip</strong>——解释器是什么、<code>py -m pip install</code> 到底把东西装到了哪、为什么要虚拟环境。装好环境，就正式开工。</p>`,43)])])}const k=t(n,[["render",p]]);export{g as __pageData,k as default};
